<?php
/* =====================================================================
   INSTALADOR · La Calle de las Aves y las Flores
   ---------------------------------------------------------------------
   Ábrelo UNA sola vez en el navegador (https://tudominio.com/setup.php),
   define la contraseña de administrador y presiona "Instalar".
   Cuando termine, BÓRRALO del servidor por seguridad.
   ===================================================================== */
require_once __DIR__ . '/db.php';

$ya = false;
try {
    $ya = (bool) db()->query("SHOW TABLES LIKE 'murales'")->fetch();
} catch (Throwable $e) { $ya = false; }

$mensaje = '';
$hecho = false;

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $pass = trim($_POST['pass'] ?? '');
    $reset = !empty($_POST['reset']);
    if (strlen($pass) < 6) {
        $mensaje = 'La contraseña debe tener al menos 6 caracteres.';
    } else {
        try {
            $pdo = db();
            $pdo->exec("SET NAMES utf8mb4");

            if ($reset) {
                foreach (['solicitudes','codigos','resenas','videos','aliados','murales','config'] as $t) {
                    $pdo->exec("DROP TABLE IF EXISTS `$t`");
                }
            }

            $pdo->exec("CREATE TABLE IF NOT EXISTS config (
                clave VARCHAR(64) PRIMARY KEY,
                valor LONGTEXT
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            $pdo->exec("CREATE TABLE IF NOT EXISTS murales (
                id INT AUTO_INCREMENT PRIMARY KEY,
                num VARCHAR(8), nombre VARCHAR(160), cientifico VARCHAR(160),
                descripcion TEXT, tags VARCHAR(255), color VARCHAR(16),
                img LONGTEXT, seleccionado_por VARCHAR(160) DEFAULT '', orden INT DEFAULT 0
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            $pdo->exec("CREATE TABLE IF NOT EXISTS aliados (
                id INT AUTO_INCREMENT PRIMARY KEY,
                nombre VARCHAR(160), img LONGTEXT, orden INT DEFAULT 0
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            $pdo->exec("CREATE TABLE IF NOT EXISTS videos (
                id INT AUTO_INCREMENT PRIMARY KEY,
                youtube_id VARCHAR(64), orden INT DEFAULT 0
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            $pdo->exec("CREATE TABLE IF NOT EXISTS resenas (
                id INT AUTO_INCREMENT PRIMARY KEY,
                texto TEXT, quien VARCHAR(160), negocio VARCHAR(160),
                estrellas TINYINT DEFAULT 5, orden INT DEFAULT 0
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            $pdo->exec("CREATE TABLE IF NOT EXISTS codigos (
                codigo VARCHAR(64) PRIMARY KEY, pct INT
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            $pdo->exec("CREATE TABLE IF NOT EXISTS solicitudes (
                id INT AUTO_INCREMENT PRIMARY KEY,
                numero VARCHAR(32), fecha VARCHAR(64),
                nombre VARCHAR(160), identificacion VARCHAR(64), negocio VARCHAR(160),
                direccion VARCHAR(255), telefono VARCHAR(64), correo VARCHAR(160),
                mural_num VARCHAR(8), mural_nombre VARCHAR(160),
                ancho DECIMAL(10,2), alto DECIMAL(10,2), m2 DECIMAL(12,2),
                total DECIMAL(14,2), a_comparte DECIMAL(14,2), a_inst DECIMAL(14,2),
                codigo VARCHAR(64), codigo_pct INT, dcto DECIMAL(14,2), pagar DECIMAL(14,2),
                creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            /* Configuración inicial */
            $cond = "1. Esta cotización tiene una validez de 30 días calendario.\n2. El apoyo de Manizales Comparte y el apoyo institucional están sujetos a disponibilidad de cupos del programa.\n3. El valor incluye adaptación del diseño, materiales e instalación del mural sobre la persiana o reja del establecimiento.\n4. El establecimiento se compromete a conservar el mural y permitir su iluminación nocturna.\n5. El pago se realiza una vez confirmada la programación de la intervención.";
            cfg_set('admin_hash', password_hash($pass, PASSWORD_DEFAULT));
            cfg_set('precioM2', '250000');
            cfg_set('pctComparte', '15');
            cfg_set('pctInstitucional', '15');
            cfg_set('correoDestino', CORREO_DESTINO);
            cfg_set('condiciones', $cond);

            /* Sembrar murales si la tabla está vacía */
            if ((int)$pdo->query('SELECT COUNT(*) c FROM murales')->fetch()['c'] === 0) {
                $murales = [
    [1, '01', 'Guacamaya azulamarilla', 'Ara ararauna', 'Una presencia de gran formato, reconocible por el contraste entre el azul intenso, el amarillo dorado y los matices verdes. Dentro del recorrido urbano funciona como una pieza protagonista: transmite vitalidad, diversidad y exuberancia tropical.', 'Azul intenso||Amarillo dorado||Presencia tropical', '#E86A17', 'data:image/jpeg;base64,'],
    [2, '02', 'Tángara de corona naranja', 'Identificación visual preliminar', 'Ave pequeña y delicada, con una corona naranja que resalta sobre tonos verdes, grises y turquesa. Su mural aporta ligereza, movimiento y una transición luminosa entre hojas y flores.', 'Corona naranja||Verde suave||Delicadeza', '#6E9A31', 'data:image/jpeg;base64,'],
    [3, '03', 'Barranquero andino', 'Momotus aequatorialis', 'Se distingue por el antifaz oscuro, el ojo rojizo y los matices verdes y turquesa de la cabeza y el pecho. La composición crea un punto de atención elegante y misterioso, asociado con los bosques andinos.', 'Turquesa||Ojo rojizo||Bosque andino', '#9E1B3C', 'data:image/jpeg;base64,'],
    [4, '04', 'Atrapamoscas pechirrojo', 'Pyrocephalus rubinus', 'Su pecho rojo encendido contrasta con el plumaje oscuro y el fondo violeta. La postura sobre la rama convierte la pieza en un acento enérgico y muy visible bajo la iluminación nocturna cálida.', 'Rojo vivo||Fondo violeta||Energía', '#5B2AC7', 'data:image/jpeg;base64,'],
    [5, '05', 'Copetón', 'Zonotrichia capensis', 'Ave cercana a parques, jardines y entornos urbanos, reconocible por la pequeña cresta, el cuello listado y sus tonos tierra. El mural conecta la biodiversidad cotidiana con la vida comercial y barrial de la calle.', 'Tonos tierra||Cresta||Vida urbana', '#4A3AB8', 'data:image/jpeg;base64,'],
    [6, '06', 'Tángara montañera de alas azules', 'Anisognathus somptuosus', 'El amarillo brillante, el negro profundo y las alas azules forman una imagen de alto contraste. Rodeada de ramas de café, la composición enlaza la avifauna de montaña con el paisaje cultural cafetero.', 'Amarillo||Alas azules||Paisaje cafetero', '#1E4D33', 'data:image/jpeg;base64,'],
    [7, '07', 'Colibrí chillón', 'Colibri coruscans', 'Los reflejos verdes, azules y violetas, junto con la cola abierta, transmiten ligereza y movimiento. En el conjunto representa la relación directa entre aves y flores, además de la energía de la polinización.', 'Iridescencia||Movimiento||Flores', '#E01E6B', 'data:image/jpeg;base64,'],                ];
                $st = $pdo->prepare('INSERT INTO murales (orden, num, nombre, cientifico, descripcion, tags, color, img, seleccionado_por)
                                     VALUES (?,?,?,?,?,?,?,?,"")');
                foreach ($murales as $m) { $st->execute($m); }
            }

            /* Reseñas de ejemplo si la tabla está vacía */
            if ((int)$pdo->query('SELECT COUNT(*) c FROM resenas')->fetch()['c'] === 0) {
                $r = $pdo->prepare('INSERT INTO resenas (texto, quien, negocio, estrellas, orden) VALUES (?,?,?,?,?)');
                $r->execute(['Antes la persiana cerrada era una pared gris más. Ahora la gente se detiene a tomarle fotos al mural y el sector se siente mucho más seguro de noche.', 'Nombre del comerciante', 'Nombre del establecimiento', 5, 1]);
                $r->execute(['El proceso fue muy fácil: elegimos el ave, nos cotizaron en minutos y con el apoyo de Manizales Comparte el costo fue muy accesible.', 'Nombre del comerciante', 'Nombre del establecimiento', 5, 2]);
                $r->execute(['El mural le dio identidad a nuestra cuadra. Los vecinos ya hablan de "la calle de las aves" y eso atrae visitantes que antes no pasaban por aquí.', 'Nombre del comerciante', 'Nombre del establecimiento', 5, 3]);
            }

            /* Códigos de ejemplo */
            $pdo->exec("INSERT IGNORE INTO codigos (codigo, pct) VALUES ('MZLSCOMPARTE', 10), ('AVESYFLORES', 5)");

            $hecho = true;
            $mensaje = '¡Instalación completada! Ya puedes borrar este archivo (setup.php) del servidor.';
        } catch (Throwable $e) {
            $mensaje = 'Error durante la instalación: ' . $e->getMessage();
        }
    }
}
?><!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Instalador · La Calle de las Aves y las Flores</title>
<style>
body{font-family:system-ui,sans-serif;background:#0B1530;color:#fff;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0;padding:20px}
