input[type=password]{width:100%;padding:12px 14px;border-radius:10px;border:1px solid #2A3A66;background:#0B1530;color:#fff;font-size:1rem;box-sizing:border-box}
.chk{display:flex;gap:8px;align-items:flex-start;margin-top:16px;font-size:.78rem;color:#98A0C0}
