a{color:#FFD122}
</style></head><body><div class="caja">
<h1>🐦 Instalador</h1>
<p class="sub">La Calle de las Aves y las Flores · Manizales Comparte</p>
<?php if ($mensaje): ?>
  <div class="msg <?= $hecho ? 'ok' : 'err' ?>"><?= htmlspecialchars($mensaje) ?></div>
<?php endif; ?>
<?php if ($hecho): ?>
  <div class="msg aviso" style="margin-top:14px">⚠ Paso final de seguridad: <b>borra el archivo setup.php</b> del servidor ahora mismo. Luego entra a <a href="index.html">tu página</a> y prueba el acceso de administrador con la contraseña que definiste.</div>
<?php else: ?>
  <?php if ($ya): ?>
    <div class="msg aviso">Ya existe una instalación. Si vuelves a instalar sin marcar la casilla, se conservan tus datos. Marca "Reiniciar" solo si quieres borrar todo y empezar de cero.</div>
  <?php endif; ?>
  <form method="post">
    <label for="pass">Contraseña de administrador (mínimo 6 caracteres)</label>
    <input type="password" id="pass" name="pass" required minlength="6" autocomplete="new-password">
    <?php if ($ya): ?>
    <div class="chk"><input type="checkbox" id="reset" name="reset" value="1"><label for="reset" style="color:#98A0C0;font-weight:400;margin:0">Reiniciar: borrar todos los datos existentes y empezar de cero</label></div>
    <?php endif; ?>
    <button type="submit">Instalar</button>
  </form>
<?php endif; ?>
</div></body></html>
